import React, { useState } from 'react';
import './ExcursionCard.css';

import likeIcon from '../assets/icons/like.svg';
import heartFilledIcon from '../assets/icons/heart2.svg';

const ExcursionCard = ({ excursion }) => {
  const [isFavorite, setIsFavorite] = useState(false);

  const handleFavoriteClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsFavorite((prev) => !prev);
  };

  return (
    <div className="excursion-card">
      <div className="excursion-card__image-wrapper">
        <img
          src={excursion.image}
          alt={excursion.title}
          className="excursion-card__image"
        />

        {/* ИЗБРАННОЕ */}
        <button
          className="excursion-card__favorite"
          onClick={handleFavoriteClick}
          title={
            isFavorite
              ? 'Удалить из избранного'
              : 'Добавить в избранное'
          }
        >
          <img
            src={isFavorite ? heartFilledIcon : likeIcon}
            alt="Избранное"
            width="32"
            height="32"
          />
        </button>
      </div>

      <div className="excursion-card__body">
        <h3 className="excursion-card__title">
          {excursion.title}
        </h3>

        <p className="excursion-card__location">
          {excursion.country}, {excursion.city}
        </p>

        <div className="excursion-card__info">
          <span className="excursion-card__price">
            {excursion.price.toLocaleString()} ₽
          </span>

          <span className="excursion-card__rating">
            ★ {excursion.rating}
          </span>
        </div>

        <button className="excursion-card__button">
          В корзину
        </button>
      </div>
    </div>
  );
};

export default ExcursionCard;
